### 爬楼梯算法拓展
如果爬楼梯的步长由参数控制，则：
```cpp
class Solution {
public:
    int climbStairs(int n, int step) {
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= step; j++) {
                if (i - j >= 0) dp[i] += dp[i - j];
            }
        }
        return dp[n];
    }
}
```
